<?php
use App\Models\CustomerPurchaseRequest; use Illuminate\Auth\Access\AuthorizationException;
use function Livewire\Volt\layout; use function Livewire\Volt\mount; use function Livewire\Volt\state;
layout('layouts.customer'); state(['purchaseRequest'=>null]);
mount(function(CustomerPurchaseRequest $customerPurchaseRequest){$account=auth('customer')->user(); if((int)$customerPurchaseRequest->company_id!==(int)$account->company_id||(int)$customerPurchaseRequest->customer_account_id!==(int)$account->id)throw new AuthorizationException; $this->purchaseRequest=$customerPurchaseRequest->load(['branch','items','quotations']);});
?>
<div><x-page-header :title="$purchaseRequest->request_number" description="Purchase request details" :breadcrumbs="['Purchase Requests'=>route('customer.purchase-requests.index'),$purchaseRequest->request_number=>null]"/><div class="grid gap-6 lg:grid-cols-3"><x-card class="lg:col-span-2" title="Requested Items"><x-table :headers="['Product','Unit','Requested','Base Quantity']">@foreach($purchaseRequest->items as $item)<tr><td class="px-4 py-3 font-bold">{{ $item->product_name_snapshot }}</td><td class="px-4 py-3">{{ $item->transaction_unit_name_snapshot }}</td><td class="px-4 py-3">{{ \App\Support\NumberFormatter::quantity($item->transaction_quantity) }}</td><td class="px-4 py-3">{{ \App\Support\NumberFormatter::quantity($item->base_quantity) }} {{ $item->base_unit_name_snapshot }}</td></tr>@endforeach</x-table></x-card><x-card title="Status"><p class="text-xl font-black">{{ str($purchaseRequest->status)->headline() }}</p><p class="mt-2 text-sm text-slate-500">{{ $purchaseRequest->branch?->name }} · {{ $purchaseRequest->submitted_at->format('d M Y H:i') }}</p>@foreach($purchaseRequest->quotations as $quotation)<a href="{{ route('customer.quotations.show',$quotation) }}" class="mt-4 block rounded-xl border p-3 font-bold text-build-orange">{{ $quotation->quotation_number }} · {{ str($quotation->status)->headline() }}</a>@endforeach</x-card></div></div>
